package com.vandorlabs.neoforge.client;
import com.vandorlabs.neoforge.ModernFinishCatalog;
import com.vandorlabs.neoforge.light.*;
import com.vandorlabs.redstone.ChannelList;
import com.vandorlabs.tiles.HousingFinishCatalog;
import com.vandorlabs.render.TextureLayoutMode;
import com.vandorlabs.ui.*;
import java.util.*;
import java.util.function.Consumer;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.*;
import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.player.Inventory;
import net.neoforged.neoforge.network.PacketDistributor;
/** Inactive dedicated Source Light editor; picker and slider behavior use the existing native widgets. */
public final class NativeLightScreen extends AbstractContainerScreen<NativeLightMenu> {
 private final Consumer<NativeLightSettingsEdit> send;private final Map<Integer,Button> buttons=new LinkedHashMap<>();private final Map<Integer,NativeMaterialPicker> pickers=new HashMap<>();
 private ProgrammableDialogLayout panel;private NativeMaterialPicker picker;private EditBox channels;private NativeIntegerSlider slider;private int page;private boolean draggingSlider;
 private int selected,offSelected,housing,level,offset,trigger,layout;private boolean join,small,signalBrightness;private String draft;private ChannelList lastValidChannels;
 public NativeLightScreen(NativeLightMenu menu,Inventory inventory,Component title){this(menu,inventory,title,edit->PacketDistributor.sendToServer(new LightSettingsPayload(edit)));}
 public NativeLightScreen(NativeLightMenu menu,Inventory inventory,Component title,Consumer<NativeLightSettingsEdit> send){super(menu,inventory,title);this.send=Objects.requireNonNull(send);var tile=menu.tile;var own=tile.settings().light();selected=own.faceTexture<0?HousingFinishCatalog.legacyCount()+own.texture:own.faceTexture;offSelected=own.offFaceTexture;housing=tile.inheritedSettings().housing().mainTexture;level=own.configuredLevel;offset=own.offset;trigger=own.trigger;layout=tile.inheritedSettings().housing().layout();join=own.join;small=tile.visual().small();signalBrightness=own.signalBrightness;lastValidChannels=tile.getRedstoneChannels();draft=lastValidChannels.toString();}
 public ProgrammableDialogLayout panel(){return panel;}public NativeMaterialPicker activePicker(){return picker;}public EditBox channelField(){return channels;}public NativeIntegerSlider slider(){return slider;}public Button button(int id){return buttons.get(id);}public int page(){return page;}public NativeLightEdit choices(){return new NativeLightEdit(selected,offSelected,level,join,housing,trigger,small,layout,signalBrightness,offset);}public NativeLightSettingsEdit edit(){return new NativeLightSettingsEdit(menu.tile.getBlockPos(),menu.containerId,choices(),lastValidChannels);}public String sliderLabel(){return (signalBrightness?"Signal offset: ":"Light level: ")+(signalBrightness?offset:level);}
 @Override protected void init(){super.init();panel=new ProgrammableDialogLayout(width,height);imageWidth=panel.width;imageHeight=panel.height;leftPos=panel.left;topPos=panel.top;rebuild(true);}
 private void option(int id,int x,int y,int width,String text,boolean enabled){var button=Button.builder(Component.literal(text),ignored->action(id,1)).bounds(x,y,width,20).build();button.active=enabled;buttons.put(id,button);addRenderableWidget(button);}
 private void rebuild(boolean center){if(channels!=null)draft=channels.getValue();if(picker!=null)picker.closeInventory();clearWidgets();buttons.clear();int tabWidth=(panel.width-24)/4;String[] tabs={"ON","OFF","Sides","Redstone"};for(int i=0;i<4;i++)option(90+i,panel.left+12+i*tabWidth,panel.top+30,tabWidth-2,tabs[i],page!=i);
  picker=null;slider=null;if(page<3){int selected=page==0?this.selected:page==1?(offSelected<0?this.selected:offSelected):housing;picker=pickers.computeIfAbsent(page,key->new NativeMaterialPicker(selected,id->NativeLightPickerPolicy.selectable(id,key==1),this::choose));picker.select(selected,false);picker.layout(panel.listX,panel.top+54,panel.listWidth,panel.rows(true),center);addRenderableWidget(picker.searchField());option(101,panel.controlsX,panel.top+54,154,"Join: "+(join?"ON":"OFF"),true);if(menu.tile.kind()==NativeLightBlock.Kind.FRAME)option(103,panel.controlsX,panel.top+76,154,"Size: "+(small?"Small":"Full"),true);if(page==1)option(105,panel.controlsX,panel.top+96,154,offSelected<0?"OFF: Automatic":"Use automatic OFF",offSelected>=0);else option(104,panel.controlsX,panel.top+96,154,"Texture: "+TextureLayoutMode.label(layout),true);
   if(page==0){slider=new NativeIntegerSlider(panel.controlsX+4,panel.top+152,146,14,signalBrightness?-15:0,15,signalBrightness?offset:level,value->Component.empty(),value->{if(signalBrightness){offset=value;apply();}else if(level!=value){level=value;apply();}});addRenderableWidget(slider);}}
  channels=new EditBox(font,panel.left+12,panel.top+68,panel.width-24,18,Component.literal("Receive channels"));channels.setMaxLength(ChannelList.MAX_TEXT_LENGTH);channels.setFilter(value->value.matches("[0-9, ]*"));channels.setValue(draft);channels.visible=channels.active=page==3;channels.setResponder(value->{draft=value;apply();});addRenderableWidget(channels);if(page==3)option(102,panel.left+12,panel.top+96,panel.width-24,"Activation: "+RedstoneActivation.label(signalBrightness?3:trigger),true);option(100,panel.controlsX,panel.doneY,154,Component.translatable("gui.done").getString(),true);validate();}
 private boolean validate(){boolean valid=ChannelList.parse(channels==null?draft:channels.getValue())!=null;var done=buttons.get(100);if(done!=null)done.active=valid;if(channels!=null)channels.setTextColor(valid?0xE0E0E0:0xFF7777);return valid;}
 private boolean apply(){var parsed=ChannelList.parse(channels==null?draft:channels.getValue());if(parsed==null){validate();return false;}lastValidChannels=parsed;send.accept(edit());validate();return true;}
 public void choose(int texture){if(page>=3||!ModernFinishCatalog.validChoice(texture))throw new IllegalArgumentException("Invalid Light picker selection");if(page==0)selected=texture;else if(page==1)offSelected=texture;else housing=texture;apply();rebuild(false);}
 public void action(int id,int direction){if(picker!=null)picker.closeInventory();if(id>=90&&id<=93){page=id-90;rebuild(true);return;}if(id==100){if(apply()){if(minecraft.player!=null)onClose();else minecraft.setScreen(null);}return;}switch(id){case 101->join=!join;case 103->{if(menu.tile.kind()!=NativeLightBlock.Kind.FRAME)return;small=!small;}case 104->layout=DialogInput.cycle(layout,3,direction);case 105->{if(offSelected<0)return;offSelected=-1;}case 102->{int choice=DialogInput.cycle(signalBrightness?3:trigger,4,direction);signalBrightness=choice==3;trigger=signalBrightness?2:choice;}default->{return;}}apply();rebuild(false);}
 @Override public boolean mouseClicked(double x,double y,int button){if(button==0&&slider!=null&&x>=panel.controlsX&&x<=panel.controlsX+154&&y>=slider.getY()&&y<slider.getY()+slider.getHeight()){draggingSlider=slider.mouseClicked(Math.max(slider.getX(),Math.min(slider.getX()+slider.getWidth()-1,x)),y,0);if(draggingSlider){setFocused(slider);return true;}}if(button==1)for(var entry:buttons.entrySet())if(entry.getKey()>=101&&entry.getKey()<=104&&entry.getValue().active&&entry.getValue().isMouseOver(x,y)){action(entry.getKey(),-1);return true;}return picker!=null&&picker.click(x,y,button)||super.mouseClicked(x,y,button);}
 @Override public boolean keyPressed(int key,int scan,int modifiers){if(picker!=null&&picker.keyPressed(key,scan,modifiers))return true;if(page==3&&channels.isFocused()&&key!=256&&key!=257&&key!=335){channels.keyPressed(key,scan,modifiers);return true;}if(key==257||key==335){action(100,1);return true;}return super.keyPressed(key,scan,modifiers);}
 @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(draggingSlider&&slider!=null&&button==0)return slider.mouseDragged(x,y,button,dx,dy);return picker!=null&&picker.drag(x,y)||super.mouseDragged(x,y,button,dx,dy);}
 @Override public boolean mouseReleased(double x,double y,int button){draggingSlider=false;if(slider!=null)slider.mouseReleased(x,y,button);if(picker!=null)picker.release();return super.mouseReleased(x,y,button);}
 @Override public boolean mouseScrolled(double x,double y,double horizontal,double vertical){return picker!=null&&picker.wheel(x,y,vertical)||super.mouseScrolled(x,y,horizontal,vertical);}
 @Override public void renderBackground(GuiGraphics g,int x,int y,float partial){g.fillGradient(0,0,width,height,0xC0101010,0xD0101010);renderBg(g,partial,x,y);}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){g.fill(panel.left,panel.top,panel.left+panel.width,panel.top+panel.height,0xEE18212C);g.fill(panel.left,panel.top,panel.left+panel.width,panel.top+26,0xFF304858);g.drawString(font,title,panel.left+12,panel.top+10,0xFFFFFFFF,false);if(picker!=null)picker.render(g,x,y);if(page==0)g.drawString(font,sliderLabel(),panel.controlsX,panel.top+136,0xFFDAE8F0,false);if(page==3)g.drawString(font,"Receive channels",panel.left+12,panel.top+54,0xFFDAE8F0,false);}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){}@Override public boolean isPauseScreen(){return false;}
}
